sql:
SELECT 100.0 * SUM(riders) FILTER (WHERE payment_method = 'omny') / NULLIF(SUM(riders), 0) AS omny_percentage
FROM gold.fct_subway_ridership_hourly
WHERE hour_date >= DATE '2026-09-01' AND hour_date < DATE '2026-09-21';

SELECT COUNT(*) AS datasets_with_latest_update_error
FROM gold.ops_source_freshness
WHERE last_error IS NOT NULL AND TRIM(last_error) <> '';

SELECT COUNT(*) AS station_count
FROM gold.dim_bike_station
WHERE is_new_jersey = TRUE;
